namespace Sigov.Infrastructure.Integracoes;

public sealed class ApiCredentialRepository : BaseRepository, IApiCredentialRepository
{
    private readonly DapperContext _context; public ApiCredentialRepository(DapperContext context)=>_context=context;
    public async Task<PagedResult<ApiCredentialResponse>> ListarAsync(long tenantId, ApiCredentialFiltro filtro, CancellationToken ct){var page=Math.Max(1,filtro.Page);var size=Math.Clamp(filtro.PageSize,1,100);const string sql="select id,nome,client_id as ClientId,api_key_prefix as ApiKeyPrefix,coalesce(scopes,'[]'::jsonb)::text as ScopesJson,status,expira_at as ExpiraAt,last_used_at as LastUsedAt from sigov.api_credential where tenant_id=@TenantId and is_deleted=false and (@Status is null or status=@Status) order by id desc limit @Size offset @Offset; select count(1) from sigov.api_credential where tenant_id=@TenantId and is_deleted=false and (@Status is null or status=@Status);"; using var cn=_context.CreateConnection(); using var g=await cn.QueryMultipleAsync(Command(sql,new{TenantId=tenantId,filtro.Status,Size=size,Offset=(page-1)*size},ct)).ConfigureAwait(false); var rows=(await g.ReadAsync<Row>().ConfigureAwait(false)).Select(ToResponse).ToList(); return new PagedResult<ApiCredentialResponse>(rows,page,size,await g.ReadSingleAsync<long>().ConfigureAwait(false));}
    public async Task<ApiCredentialResponse?> ObterAsync(long tenantId,long id,CancellationToken ct){const string sql="select id,nome,client_id as ClientId,api_key_prefix as ApiKeyPrefix,coalesce(scopes,'[]'::jsonb)::text as ScopesJson,status,expira_at as ExpiraAt,last_used_at as LastUsedAt from sigov.api_credential where tenant_id=@TenantId and id=@Id and is_deleted=false;"; using var cn=_context.CreateConnection(); var r=await cn.QuerySingleOrDefaultAsync<Row>(Command(sql,new{TenantId=tenantId,Id=id},ct)).ConfigureAwait(false); return r is null?null:ToResponse(r);}
    public async Task<long> CriarAsync(long tenantId,ApiCredentialCreateRequest request,string prefix,string hash,string algoritmo,long? usuarioId,CancellationToken ct){const string sql="insert into sigov.api_credential (tenant_id,nome,descricao,client_id,api_key_prefix,api_key_hash,algoritmo_hash,scopes,permitido_ips,expira_at,status,created_by) values (@TenantId,@Nome,@Descricao,@ClientId,@Prefix,@Hash,@Algoritmo,cast(@Scopes as jsonb),cast(@Ips as jsonb),@ExpiraAt,'ATIVA',@UsuarioId) returning id;"; using var cn=_context.CreateConnection(); return await cn.ExecuteScalarAsync<long>(Command(sql,new{TenantId=tenantId,request.Nome,request.Descricao,request.ClientId,Prefix=prefix,Hash=hash,Algoritmo=algoritmo,Scopes=JsonSerializer.Serialize(request.Scopes??Array.Empty<string>()),Ips=JsonSerializer.Serialize(request.PermitidoIps??Array.Empty<string>()),request.ExpiraAt,UsuarioId=usuarioId},ct)).ConfigureAwait(false);}
    public async Task AlterarStatusAsync(long tenantId,long id,string status,long? usuarioId,CancellationToken ct){const string sql="update sigov.api_credential set status=@Status,ativo=(@Status='ATIVA'),updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and id=@Id and is_deleted=false;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{TenantId=tenantId,Id=id,Status=status,UsuarioId=usuarioId},ct)).ConfigureAwait(false);}
    private static ApiCredentialResponse ToResponse(Row r)=>new(r.Id,r.Nome,r.ClientId,r.ApiKeyPrefix,ParseList(r.ScopesJson),r.Status,r.ExpiraAt,r.LastUsedAt); private static IReadOnlyCollection<string> ParseList(string json){try{return JsonSerializer.Deserialize<IReadOnlyCollection<string>>(json)??Array.Empty<string>();}catch(JsonException){return Array.Empty<string>();}} private sealed record Row(long Id,string Nome,string ClientId,string ApiKeyPrefix,string ScopesJson,string Status,DateTimeOffset? ExpiraAt,DateTimeOffset? LastUsedAt);
}
public sealed class IntegracaoSistemaRepository : BaseRepository, IIntegracaoSistemaRepository
{
    private readonly DapperContext _context; public IntegracaoSistemaRepository(DapperContext c)=>_context=c;
    public async Task<PagedResult<IntegracaoSistemaResponse>> ListarAsync(long tenantId,IntegracaoSistemaFiltro f,CancellationToken ct){var p=Math.Max(1,f.Page);var s=Math.Clamp(f.PageSize,1,100);const string sql="select id,codigo,nome,tipo_integracao as TipoIntegracao,ambiente,base_url as BaseUrl,status,ativo from sigov.integracao_sistema where tenant_id=@TenantId and is_deleted=false and (@Tipo is null or tipo_integracao=@Tipo) and (@Status is null or status=@Status) order by id desc limit @Size offset @Offset; select count(1) from sigov.integracao_sistema where tenant_id=@TenantId and is_deleted=false and (@Tipo is null or tipo_integracao=@Tipo) and (@Status is null or status=@Status);"; using var cn=_context.CreateConnection(); using var g=await cn.QueryMultipleAsync(Command(sql,new{TenantId=tenantId,Tipo=f.TipoIntegracao,Status=f.Status,Size=s,Offset=(p-1)*s},ct)).ConfigureAwait(false); return new PagedResult<IntegracaoSistemaResponse>((await g.ReadAsync<IntegracaoSistemaResponse>().ConfigureAwait(false)).AsList(),p,s,await g.ReadSingleAsync<long>().ConfigureAwait(false));}
    public async Task<IntegracaoSistemaResponse?> ObterAsync(long tenantId,long id,CancellationToken ct){const string sql="select id,codigo,nome,tipo_integracao as TipoIntegracao,ambiente,base_url as BaseUrl,status,ativo from sigov.integracao_sistema where tenant_id=@TenantId and id=@Id and is_deleted=false;"; using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<IntegracaoSistemaResponse>(Command(sql,new{TenantId=tenantId,Id=id},ct)).ConfigureAwait(false);}
    public async Task<long> CriarAsync(long tenantId,IntegracaoSistemaCreateRequest r,long? u,CancellationToken ct){const string sql="insert into sigov.integracao_sistema (tenant_id,codigo,nome,tipo,tipo_integracao,ambiente,base_url,status,configuracao,segredo_configurado,created_by) values (@TenantId,@Codigo,@Nome,@TipoIntegracao,@TipoIntegracao,@Ambiente,@BaseUrl,'ATIVA',cast(@Configuracao as jsonb),false,@UsuarioId) returning id;"; using var cn=_context.CreateConnection(); return await cn.ExecuteScalarAsync<long>(Command(sql,new{TenantId=tenantId,r.Codigo,r.Nome,r.TipoIntegracao,r.Ambiente,r.BaseUrl,Configuracao=JsonSerializer.Serialize(r.Configuracao??new{}),UsuarioId=u},ct)).ConfigureAwait(false);}
    public async Task AtualizarAsync(long tenantId,long id,IntegracaoSistemaUpdateRequest r,long? u,CancellationToken ct){const string sql="update sigov.integracao_sistema set nome=@Nome,tipo=@TipoIntegracao,tipo_integracao=@TipoIntegracao,ambiente=@Ambiente,base_url=@BaseUrl,status=@Status,configuracao=cast(@Configuracao as jsonb),ativo=@Ativo,updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and id=@Id and is_deleted=false;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{TenantId=tenantId,Id=id,r.Nome,r.TipoIntegracao,r.Ambiente,r.BaseUrl,r.Status,Configuracao=JsonSerializer.Serialize(r.Configuracao??new{}),r.Ativo,UsuarioId=u},ct)).ConfigureAwait(false);}
    public async Task ExcluirAsync(long tenantId,long id,long? u,CancellationToken ct){const string sql="update sigov.integracao_sistema set is_deleted=true,ativo=false,deleted_at=now(),deleted_by=@UsuarioId,updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and id=@Id and is_deleted=false;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{TenantId=tenantId,Id=id,UsuarioId=u},ct)).ConfigureAwait(false);}
}
public sealed class WebhookRepository : BaseRepository, IWebhookRepository
{ private readonly DapperContext _context; public WebhookRepository(DapperContext c)=>_context=c;
 public async Task<long> RegistrarRecebidoAsync(long? tenantId,string origem,WebhookReceberRequest r,string headersJson,string assinatura,bool? assinaturaValida,string? ip,string? userAgent,Guid correlationId,CancellationToken ct){const string sql="insert into sigov.webhook_recebido (tenant_id,origem,evento,headers,payload,assinatura,assinatura_valida,idempotency_key,status,ip,user_agent,correlation_id) values (@TenantId,@Origem,@Evento,cast(@Headers as jsonb),cast(@Payload as jsonb),@Assinatura,@AssinaturaValida,@IdempotencyKey,'RECEBIDO',@Ip,@UserAgent,@CorrelationId) returning id;"; using var cn=_context.CreateConnection(); return await cn.ExecuteScalarAsync<long>(Command(sql,new{TenantId=tenantId,Origem=origem,r.Evento,Headers=headersJson,Payload=JsonSerializer.Serialize(r.Payload??new{}),Assinatura=assinatura,AssinaturaValida=assinaturaValida,r.IdempotencyKey,Ip=ip,UserAgent=userAgent,CorrelationId=correlationId},ct)).ConfigureAwait(false);}
 public async Task<PagedResult<WebhookRecebidoResponse>> ListarRecebidosAsync(long tenantId,WebhookRecebidoFiltro f,CancellationToken ct){var p=Math.Max(1,f.Page);var s=Math.Clamp(f.PageSize,1,100);const string sql="select id,origem,evento,status,assinatura_valida as AssinaturaValida,idempotency_key as IdempotencyKey,created_at as CreatedAt from sigov.webhook_recebido where tenant_id=@TenantId and (@Status is null or status=@Status) order by id desc limit @Size offset @Offset; select count(1) from sigov.webhook_recebido where tenant_id=@TenantId and (@Status is null or status=@Status);"; using var cn=_context.CreateConnection(); using var g=await cn.QueryMultipleAsync(Command(sql,new{TenantId=tenantId,f.Status,Size=s,Offset=(p-1)*s},ct)).ConfigureAwait(false); return new PagedResult<WebhookRecebidoResponse>((await g.ReadAsync<WebhookRecebidoResponse>().ConfigureAwait(false)).AsList(),p,s,await g.ReadSingleAsync<long>().ConfigureAwait(false));}
 public async Task<PagedResult<WebhookEnviadoResponse>> ListarEnviadosAsync(long tenantId,WebhookRecebidoFiltro f,CancellationToken ct){var p=Math.Max(1,f.Page);var s=Math.Clamp(f.PageSize,1,100);const string sql="select id,destino,url,evento,status,tentativas,created_at as CreatedAt from sigov.webhook_enviado where tenant_id=@TenantId and (@Status is null or status=@Status) order by id desc limit @Size offset @Offset; select count(1) from sigov.webhook_enviado where tenant_id=@TenantId and (@Status is null or status=@Status);"; using var cn=_context.CreateConnection(); using var g=await cn.QueryMultipleAsync(Command(sql,new{TenantId=tenantId,f.Status,Size=s,Offset=(p-1)*s},ct)).ConfigureAwait(false); return new PagedResult<WebhookEnviadoResponse>((await g.ReadAsync<WebhookEnviadoResponse>().ConfigureAwait(false)).AsList(),p,s,await g.ReadSingleAsync<long>().ConfigureAwait(false));}
 public async Task<long> CriarEnviadoAsync(long tenantId,WebhookEnviarRequest r,long? u,CancellationToken ct){const string sql="insert into sigov.webhook_enviado (tenant_id,destino,url,evento,payload,status,created_at) values (@TenantId,@Destino,@Url,@Evento,cast(@Payload as jsonb),'PENDENTE',now()) returning id;"; using var cn=_context.CreateConnection(); _=u; return await cn.ExecuteScalarAsync<long>(Command(sql,new{TenantId=tenantId,r.Destino,r.Url,r.Evento,Payload=JsonSerializer.Serialize(r.Payload??new{})},ct)).ConfigureAwait(false);} public async Task ReprocessarAsync(long tenantId,long id,CancellationToken ct){const string sql="update sigov.webhook_recebido set status='REPROCESSAR',processado_at=null,erro=null where tenant_id=@TenantId and id=@Id;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{TenantId=tenantId,Id=id},ct)).ConfigureAwait(false);} }
public sealed class OutboxRepository : BaseRepository, IOutboxRepository
{ private readonly DapperContext _context; public OutboxRepository(DapperContext c)=>_context=c;
 public async Task<PagedResult<OutboxEventoResponse>> ListarAsync(long tenantId,OutboxFiltro f,CancellationToken ct){var p=Math.Max(1,f.Page);var s=Math.Clamp(f.PageSize,1,100);const string sql="select id,tenant_id as TenantId,tipo_evento as TipoEvento,status,tentativas,max_tentativas as MaxTentativas,dead_letter as DeadLetter,created_at as CreatedAt,correlation_id as CorrelationId from sigov.fila_evento where tenant_id=@TenantId and (@Status is null or status=@Status) and (@DeadLetter is null or dead_letter=@DeadLetter) order by id desc limit @Size offset @Offset; select count(1) from sigov.fila_evento where tenant_id=@TenantId and (@Status is null or status=@Status) and (@DeadLetter is null or dead_letter=@DeadLetter);"; using var cn=_context.CreateConnection(); using var g=await cn.QueryMultipleAsync(Command(sql,new{TenantId=tenantId,f.Status,f.DeadLetter,Size=s,Offset=(p-1)*s},ct)).ConfigureAwait(false); return new PagedResult<OutboxEventoResponse>((await g.ReadAsync<OutboxEventoResponse>().ConfigureAwait(false)).AsList(),p,s,await g.ReadSingleAsync<long>().ConfigureAwait(false));}
 public async Task<OutboxEventoResponse?> ObterAsync(long tenantId,long id,CancellationToken ct){const string sql="select id,tenant_id as TenantId,tipo_evento as TipoEvento,status,tentativas,max_tentativas as MaxTentativas,dead_letter as DeadLetter,created_at as CreatedAt,correlation_id as CorrelationId from sigov.fila_evento where tenant_id=@TenantId and id=@Id;"; using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<OutboxEventoResponse>(Command(sql,new{TenantId=tenantId,Id=id},ct)).ConfigureAwait(false);}
 public async Task<long> CriarAsync(long? tenantId,long? entidadeId,long? exercicioId,OutboxEventoCreateRequest r,long? u,CancellationToken ct){const string sql="insert into sigov.fila_evento (tenant_id,entidade_id,exercicio_id,tipo_evento,payload,headers,origem,destino,idempotency_key,correlation_id,created_by) values (@TenantId,@EntidadeId,@ExercicioId,@TipoEvento,cast(@Payload as jsonb),cast(@Headers as jsonb),@Origem,@Destino,@IdempotencyKey,@CorrelationId,@UsuarioId) returning id;"; using var cn=_context.CreateConnection(); return await cn.ExecuteScalarAsync<long>(Command(sql,new{TenantId=tenantId,EntidadeId=entidadeId,ExercicioId=exercicioId,r.TipoEvento,Payload=JsonSerializer.Serialize(r.Payload??new{}),Headers=JsonSerializer.Serialize(r.Headers??new{}),r.Origem,r.Destino,r.IdempotencyKey,r.CorrelationId,UsuarioId=u},ct)).ConfigureAwait(false);}
 public async Task ReprocessarAsync(long tenantId,long id,CancellationToken ct){const string sql="update sigov.fila_evento set status='PENDENTE',dead_letter=false,erro=null,proxima_tentativa_at=null,updated_at=now() where tenant_id=@TenantId and id=@Id;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{TenantId=tenantId,Id=id},ct)).ConfigureAwait(false);} public async Task DeadLetterAsync(long tenantId,long id,string? erro,CancellationToken ct){const string sql="update sigov.fila_evento set status='DEAD_LETTER',dead_letter=true,erro=@Erro,updated_at=now() where tenant_id=@TenantId and id=@Id;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{TenantId=tenantId,Id=id,Erro=erro},ct)).ConfigureAwait(false);} public async Task CancelarAsync(long tenantId,long id,CancellationToken ct){const string sql="update sigov.fila_evento set status='CANCELADO',updated_at=now() where tenant_id=@TenantId and id=@Id;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{TenantId=tenantId,Id=id},ct)).ConfigureAwait(false);} }
public sealed class IntegracaoLogRepository : BaseRepository, IIntegracaoLogRepository
{ private readonly DapperContext _context; public IntegracaoLogRepository(DapperContext c)=>_context=c; public async Task RegistrarAsync(long? tenantId,string direcao,string tipoEvento,string status,string? requestResumoJson,string? responseResumoJson,Guid? correlationId,CancellationToken ct){const string sql="insert into sigov.integracao_log (tenant_id,direcao,tipo_evento,status,request_resumo,response_resumo,correlation_id) values (@TenantId,@Direcao,@TipoEvento,@Status,case when @RequestResumoJson is null then null else cast(@RequestResumoJson as jsonb) end,case when @ResponseResumoJson is null then null else cast(@ResponseResumoJson as jsonb) end,@CorrelationId);"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{TenantId=tenantId,Direcao=direcao,TipoEvento=tipoEvento,Status=status,RequestResumoJson=requestResumoJson,ResponseResumoJson=responseResumoJson,CorrelationId=correlationId},ct)).ConfigureAwait(false);} }
public sealed class RemessaOficialRepository : BaseRepository, IRemessaOficialRepository
{ private readonly DapperContext _context; public RemessaOficialRepository(DapperContext c)=>_context=c; public async Task<PagedResult<RemessaOficialResponse>> ListarAsync(long tenantId,OutboxFiltro f,CancellationToken ct){var p=Math.Max(1,f.Page);var s=Math.Clamp(f.PageSize,1,100);const string sql="select id,tipo_remessa as TipoRemessa,competencia,numero,status,gerado_at as GeradoAt,enviado_at as EnviadoAt from sigov.remessa_oficial where tenant_id=@TenantId and is_deleted=false order by id desc limit @Size offset @Offset; select count(1) from sigov.remessa_oficial where tenant_id=@TenantId and is_deleted=false;"; using var cn=_context.CreateConnection(); using var g=await cn.QueryMultipleAsync(Command(sql,new{TenantId=tenantId,Size=s,Offset=(p-1)*s},ct)).ConfigureAwait(false); return new PagedResult<RemessaOficialResponse>((await g.ReadAsync<RemessaOficialResponse>().ConfigureAwait(false)).AsList(),p,s,await g.ReadSingleAsync<long>().ConfigureAwait(false));} public async Task<RemessaOficialResponse?> ObterAsync(long tenantId,long id,CancellationToken ct){const string sql="select id,tipo_remessa as TipoRemessa,competencia,numero,status,gerado_at as GeradoAt,enviado_at as EnviadoAt from sigov.remessa_oficial where tenant_id=@TenantId and id=@Id and is_deleted=false;"; using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<RemessaOficialResponse>(Command(sql,new{TenantId=tenantId,Id=id},ct)).ConfigureAwait(false);} public async Task<long> CriarAsync(long tenantId,long? entidadeId,long? exercicioId,RemessaOficialCreateRequest r,long? u,CancellationToken ct){const string sql="insert into sigov.remessa_oficial (tenant_id,entidade_id,exercicio_id,tipo_remessa,competencia,numero,status,payload,created_by) values (@TenantId,@EntidadeId,@ExercicioId,@TipoRemessa,@Competencia,@Numero,'RASCUNHO',cast(@Payload as jsonb),@UsuarioId) returning id;"; using var cn=_context.CreateConnection(); return await cn.ExecuteScalarAsync<long>(Command(sql,new{TenantId=tenantId,EntidadeId=entidadeId,ExercicioId=exercicioId,r.TipoRemessa,r.Competencia,r.Numero,Payload=JsonSerializer.Serialize(r.Payload??new{}),UsuarioId=u},ct)).ConfigureAwait(false);} public async Task AtualizarStatusDevAsync(long tenantId,long id,string status,long? u,CancellationToken ct){var field=status=="GERADA"?"gerado_at=now(),":""; var sent=status=="ENVIADA_DEV"?"enviado_at=now(),":""; var sql=$"update sigov.remessa_oficial set status=@Status,{field}{sent}updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and id=@Id and is_deleted=false;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{TenantId=tenantId,Id=id,Status=status,UsuarioId=u},ct)).ConfigureAwait(false);} }
public sealed class CertificadoDigitalRepository : BaseRepository, ICertificadoDigitalRepository
{ private readonly DapperContext _context; public CertificadoDigitalRepository(DapperContext c)=>_context=c; public async Task<PagedResult<CertificadoDigitalResponse>> ListarAsync(long tenantId,OutboxFiltro f,CancellationToken ct){var p=Math.Max(1,f.Page);var s=Math.Clamp(f.PageSize,1,100);const string sql="select id,nome,tipo_certificado as TipoCertificado,validade_fim as ValidadeFim,status,ativo from sigov.certificado_digital where tenant_id=@TenantId and is_deleted=false order by id desc limit @Size offset @Offset; select count(1) from sigov.certificado_digital where tenant_id=@TenantId and is_deleted=false;"; using var cn=_context.CreateConnection(); using var g=await cn.QueryMultipleAsync(Command(sql,new{TenantId=tenantId,Size=s,Offset=(p-1)*s},ct)).ConfigureAwait(false); return new PagedResult<CertificadoDigitalResponse>((await g.ReadAsync<CertificadoDigitalResponse>().ConfigureAwait(false)).AsList(),p,s,await g.ReadSingleAsync<long>().ConfigureAwait(false));} public async Task<CertificadoDigitalResponse?> ObterAsync(long tenantId,long id,CancellationToken ct){const string sql="select id,nome,tipo_certificado as TipoCertificado,validade_fim as ValidadeFim,status,ativo from sigov.certificado_digital where tenant_id=@TenantId and id=@Id and is_deleted=false;"; using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<CertificadoDigitalResponse>(Command(sql,new{TenantId=tenantId,Id=id},ct)).ConfigureAwait(false);} public async Task<long> CriarAsync(long tenantId,CertificadoDigitalCreateRequest r,long? u,CancellationToken ct){const string sql="insert into sigov.certificado_digital (tenant_id,nome,tipo_certificado,subject,issuer,serial_number,validade_inicio,validade_fim,storage_key,thumbprint,status,metadados,created_by) values (@TenantId,@Nome,@TipoCertificado,@Subject,@Issuer,@SerialNumber,@ValidadeInicio,@ValidadeFim,@StorageKey,@Thumbprint,'ATIVO',cast(@Metadados as jsonb),@UsuarioId) returning id;"; using var cn=_context.CreateConnection(); return await cn.ExecuteScalarAsync<long>(Command(sql,new{TenantId=tenantId,r.Nome,r.TipoCertificado,r.Subject,r.Issuer,r.SerialNumber,r.ValidadeInicio,r.ValidadeFim,r.StorageKey,r.Thumbprint,Metadados=JsonSerializer.Serialize(r.Metadados??new{}),UsuarioId=u},ct)).ConfigureAwait(false);} public async Task RevogarAsync(long tenantId,long id,long? u,CancellationToken ct){const string sql="update sigov.certificado_digital set status='REVOGADO',ativo=false,updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and id=@Id and is_deleted=false;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{TenantId=tenantId,Id=id,UsuarioId=u},ct)).ConfigureAwait(false);} }
public sealed class IntegracaoDashboardRepository : BaseRepository, IIntegracaoDashboardRepository
{ private readonly DapperContext _context; public IntegracaoDashboardRepository(DapperContext c)=>_context=c; public async Task<IntegracaoDashboardResponse> ObterAsync(long tenantId,CancellationToken ct){const string sql="select (select count(1) from sigov.integracao_sistema where tenant_id=@TenantId and is_deleted=false) as TotalSistemas,(select count(1) from sigov.integracao_sistema where tenant_id=@TenantId and ativo=true and is_deleted=false) as SistemasAtivos,(select count(1) from sigov.api_credential where tenant_id=@TenantId and status='ATIVA' and is_deleted=false) as ApiCredentialsAtivas,(select count(1) from sigov.fila_evento where tenant_id=@TenantId and status='PENDENTE') as OutboxPendentes,(select count(1) from sigov.fila_evento where tenant_id=@TenantId and status='ERRO') as OutboxErro,(select count(1) from sigov.fila_evento where tenant_id=@TenantId and dead_letter=true) as OutboxDeadLetter,(select count(1) from sigov.webhook_recebido where tenant_id=@TenantId and created_at::date=current_date) as WebhooksRecebidosHoje,(select count(1) from sigov.webhook_enviado where tenant_id=@TenantId and created_at::date=current_date) as WebhooksEnviadosHoje,(select count(1) from sigov.webhook_enviado where tenant_id=@TenantId and status in ('ERRO','FALHA')) as WebhooksFalha,(select count(1) from sigov.remessa_oficial where tenant_id=@TenantId and status in ('RASCUNHO','GERADA') and is_deleted=false) as RemessasPendentes,(select count(1) from sigov.remessa_oficial where tenant_id=@TenantId and enviado_at >= date_trunc('month',now()) and is_deleted=false) as RemessasEnviadasMes,(select count(1) from sigov.certificado_digital where tenant_id=@TenantId and status='ATIVO' and is_deleted=false) as CertificadosAtivos,(select count(1) from sigov.certificado_digital where tenant_id=@TenantId and validade_fim between current_date and current_date + interval '30 days' and is_deleted=false) as CertificadosVencendo;"; using var cn=_context.CreateConnection(); var c=await cn.QuerySingleAsync<Counts>(Command(sql,new{TenantId=tenantId},ct)).ConfigureAwait(false); return new IntegracaoDashboardResponse(c.TotalSistemas,c.SistemasAtivos,c.ApiCredentialsAtivas,c.OutboxPendentes,c.OutboxErro,c.OutboxDeadLetter,c.WebhooksRecebidosHoje,c.WebhooksEnviadosHoje,c.WebhooksFalha,c.RemessasPendentes,c.RemessasEnviadasMes,c.CertificadosAtivos,c.CertificadosVencendo,Array.Empty<OutboxEventoResponse>(),Array.Empty<WebhookRecebidoResponse>(),Array.Empty<RemessaOficialResponse>(),Array.Empty<string>(),Array.Empty<string>());} private sealed record Counts(long TotalSistemas,long SistemasAtivos,long ApiCredentialsAtivas,long OutboxPendentes,long OutboxErro,long OutboxDeadLetter,long WebhooksRecebidosHoje,long WebhooksEnviadosHoje,long WebhooksFalha,long RemessasPendentes,long RemessasEnviadasMes,long CertificadosAtivos,long CertificadosVencendo); }
public sealed class IntegracaoExportacaoRepository : BaseRepository, IIntegracaoExportacaoRepository
{ private readonly DapperContext _context; public IntegracaoExportacaoRepository(DapperContext c)=>_context=c; public async Task<byte[]> ExportarAsync(long tenantId,string recurso,string formato,CancellationToken ct){var table=recurso switch{"outbox"=>"fila_evento","webhooks"=>"webhook_recebido","remessas"=>"remessa_oficial","logs"=>"integracao_log",_=>"integracao_log"}; var sql=$"select * from sigov.{table} where tenant_id=@TenantId order by id desc limit 1000;"; using var cn=_context.CreateConnection(); var rows=(await cn.QueryAsync(Command(sql,new{TenantId=tenantId},ct)).ConfigureAwait(false)).Select(r=>(IDictionary<string,object>)r).ToList(); if(formato.Equals("json",StringComparison.OrdinalIgnoreCase))return Encoding.UTF8.GetBytes(JsonSerializer.Serialize(rows)); var sb=new StringBuilder(); if(rows.Count>0){sb.AppendLine(string.Join(';',rows[0].Keys)); foreach(var r in rows)sb.AppendLine(string.Join(';',r.Values.Select(v=>Convert.ToString(v,CultureInfo.InvariantCulture)?.Replace(';',',',StringComparison.Ordinal)??string.Empty)));} return Encoding.UTF8.GetBytes(sb.ToString());} }
